if(a.rotation===0)ox=-30;else if(a.rotation===180)ox=30;else if(a.rotation===90)oy=-30;else if(a.rotation===270)oy=30;else if(Math.abs(dx)>Math.abs(dy))ox=dx<0?-30:30;else oy=dy<0?-30:30;
